import { MaskedInput, MASK_PRESETS } from '@absoluteui/components/masked-input';

/** ISO 13616 mod-97 check. */
function ibanValid(raw: string): boolean {
  const moved = raw.slice(4) + raw.slice(0, 4);
  let rest = 0;
  for (const c of moved) {
    const n = /\d/.test(c) ? c : String(c.charCodeAt(0) - 55);
    for (const d of n) rest = (rest * 10 + Number(d)) % 97;
  }
  return rest === 1;
}

const host = document.createElement('div');
document.body.append(host);
MaskedInput.create(host, {
  label: 'IBAN',
  submit: 'raw',
  ...MASK_PRESETS.iban,
  validate: (value, { complete }) => (complete && !ibanValid(value) ? 'This IBAN is not valid. Check the digits.' : null),
});

